// Enforce that the input cgltf_data is known-valid for serialization.
// Upstream parsers (not in this stub) should set this attribute on success.
if (!FUZZ_GET_ATTR_INT(data, "valid")) { FUZZ_BAIL(); }

// Use a fuzz-provided writable path. The runtime provides a temp file path
// that can be opened for writing; if opening fails, the API may return
// cgltf_result_file_not_found which we accept.
const char* path = FUZZ_PARAM_FILENAME();

// Call the target function. Inputs are owned by the fuzzer pool; we don't modify them.
cgltf_result res = cgltf_write_file(options, path, data);

// Property: According to the contract, the function either succeeds or, if fopen fails,
// returns cgltf_result_file_not_found. Other results would indicate a misuse or bug.
FUZZ_ASSERT(
    res == cgltf_result_success || res == cgltf_result_file_not_found,
    "cgltf_write_file must return success or file_not_found");

// Record that this data has been subjected to a write attempt for downstream logic.
FUZZ_SET_ATTR_INT(data, "written_once", 1);

// Validation summary: Inputs are preserved and returned; path is generated via FUZZ_PARAM_FILENAME.
// We enforce data validity via an attribute and assert the documented result domain.

// Require a valid, serializable cgltf_data graph. This attribute should be set by
// a successful parse/construct stub elsewhere; otherwise we bail to avoid UB.
if (!FUZZ_GET_ATTR_INT(data, "valid")) { FUZZ_BAIL(); }

// First pass: query required size (includes trailing null terminator)
cgltf_size required = cgltf_write(options, NULL, 0, data);

// Defensive check: a well-formed serialization should require at least 1 byte for the terminator
FUZZ_ASSERT(required > 0, "cgltf_write must report size > 0 including terminator");

// Decide whether to allocate the full required size or intentionally under-allocate to
// exercise the truncation path. Also cap allocation for fuzzer performance.
bool allocate_full = ((*FUZZ_PARAM(unsigned int)) % 2) == 0;
cgltf_size alloc = allocate_full ? required : (required > 1 ? (required - 1) : 1);
if (alloc > 2048) { alloc = 2048; }
if (alloc == 0) { alloc = 1; }

// Allocate a mutable buffer of the chosen size.
std::string buffer;
buffer.resize(static_cast<size_t>(alloc), '\0');
char* buf_ptr = &buffer[0];

// Second pass: write into the buffer (possibly truncated). The return value should remain
// the total required size regardless of provided capacity.
cgltf_size reported = cgltf_write(options, buf_ptr, alloc, data);

// Property: The total required size reported by both calls must match.
FUZZ_ASSERT(reported == required, "cgltf_write must report consistent total size");

// Mark that this data was serialized in-memory at least once.
FUZZ_SET_ATTR_INT(data, "serialized_json", 1);

// Validation summary: We validate data via attribute, exercise both size-query and write paths,
// and assert the consistency property of the API while returning inputs unchanged.

// Construct a cgltf_options object. The writer ignores most fields; keep them valid and minimal.
cgltf_options* opts = new (std::nothrow) cgltf_options; if (!opts) { FUZZ_BAIL(); }
*opts = {}; // zero-initialize: type=invalid/auto-detect, counts/callbacks cleared

// Optionally set a non-zero json_token_count to exercise codepaths that read it (even if unused by writer).
bool set_tokens = ((*FUZZ_PARAM(unsigned int)) % 2) == 0;
if (set_tokens) {
    // Keep small for performance; value meaning is parser-side only.
    opts->json_token_count = static_cast<cgltf_size>((*FUZZ_PARAM(unsigned int)) % 64);
}

// Persist and return
cgltf_options* out = opts;
// Validation: out is non-null, trivially valid for writer APIs. No ownership of external resources is assumed.

// Construct a minimal, self-contained cgltf_data graph suitable for serialization by cgltf_write.
cgltf_data* d = new (std::nothrow) cgltf_data; if (!d) { FUZZ_BAIL(); }
*d = {}; // zero-initialize all counts/pointers; represents an empty glTF with default asset

// Optionally provide a tiny binary chunk to exercise GLB paths in downstream code if enabled there.
bool attach_bin = ((*FUZZ_PARAM(unsigned int)) % 3) == 0; // ~1/3 chance
if (attach_bin) {
    // Allocate a small binary blob; size capped for performance.
    cgltf_size sz = static_cast<cgltf_size>((*FUZZ_PARAM(unsigned int)) % 256);
    if (sz == 0) sz = 1;
    unsigned char* bin = new (std::nothrow) unsigned char[static_cast<size_t>(sz)];
    if (!bin) { delete d; FUZZ_BAIL(); }
    // Fill with pseudo-random bytes from a fuzz string.
    std::string rnd = FUZZ_PARAM_STR();
    for (cgltf_size i = 0; i < sz; ++i) { bin[i] = static_cast<unsigned char>(rnd[i % rnd.size()]); }
    d->bin = bin;
    d->bin_size = sz;
}

// All array counts remain zero and pointers null; asset/extras are default-initialized.
// Mark this object as valid for writer stubs.
FUZZ_SET_ATTR_INT(d, "valid", 1);

cgltf_data* out = d;
// Validation: out is non-null and marked valid; internal pointers/counts form a consistent empty model. Leak of optional bin is acceptable in fuzzer context.
